// Same safe codec is used by local checkpoints and host-authoritative online snapshots.
const ignored=new Set(['emit','random','aiInput']);
export function encodeState(value){return JSON.stringify(value,(key,v)=>ignored.has(key)||typeof v==='function'?undefined:v instanceof Set?{$set:[...v]}:v)}
export function decodeState(text){if(typeof text!=='string'||text.length>180000)throw Error('Estado muito grande');return JSON.parse(text,(key,v)=>{if(['__proto__','constructor','prototype'].includes(key))throw Error('Chave inválida');if(typeof v==='number'&&!Number.isFinite(v))throw Error('Número inválido');if(v&&typeof v==='object'&&Object.keys(v).length===1&&Array.isArray(v.$set))return new Set(v.$set);return v})}
export function hydrateState(text,Type,emit=()=>{}){const value=decodeState(text);if(!value||typeof value!=='object'||Array.isArray(value))throw Error('Estado inválido');const actors=value.players||value.fighters;if(!Array.isArray(actors)||actors.length<1||actors.length>2)throw Error('Elenco inválido');for(const actor of actors){if(!actor?.data?.id||!Number.isFinite(actor.x)||!Number.isFinite(actor.hp))throw Error('Personagem inválido');actor.hitIds=actor.hitIds instanceof Set?actor.hitIds:new Set();}
 if(value.enemies&&(!Array.isArray(value.enemies)||value.enemies.length>32))throw Error('Inimigos inválidos');const result=Object.assign(Object.create(Type.prototype),value);result.emit=emit;result.random=Math.random;result.aiInput={};if(result.enemies){const byIndex=new Map(result.enemies.map(e=>[e.index,e]));if(result.target)result.target=byIndex.get(result.target.index)||null;for(const d of result.dangers||[])if(d.enemy)d.enemy=byIndex.get(d.enemy.index)||d.enemy;for(const p of result.projectiles||[])if(p.enemy&&typeof p.enemy==='object')p.enemy=byIndex.get(p.enemy.index)||p.enemy}return result}
